<template><v-row justify="center" class="auth-layout"><v-col cols="12" sm="9" md="6"><v-card class="auth-card pa-7"><h1 class="text-h4 font-weight-bold mb-2">Crea tu cuenta</h1><p class="text-medium-emphasis mb-6">Registra tu usuario y selecciona el rol con el que trabajará.</p><AppAlert :message="error" @clear="error=''"/><v-form v-model="valid" @submit.prevent="submit"><v-text-field v-model.trim="form.full_name" label="Nombre completo" prepend-inner-icon="mdi-account-card-outline" :rules="[v=>v?.length>=3||'Mínimo 3 caracteres']"/><v-text-field v-model.trim="form.username" label="Usuario" prepend-inner-icon="mdi-at" :rules="[v=>/^[A-Za-z0-9_.-]{3,}$/.test(v)||'Usa mínimo 3 caracteres: letras, números, _, . o -']"/><v-select v-model="form.role" label="Rol" prepend-inner-icon="mdi-account-badge-outline" :items="roles" :rules="[v=>!!v||'Selecciona un rol']"/><PasswordFields v-model="form.password"/><v-btn block size="large" color="primary" type="submit" :disabled="!valid" :loading="loading">Crear cuenta</v-btn></v-form><router-link class="d-block mt-6" to="/ingresar">Ya tengo una cuenta</router-link></v-card></v-col></v-row></template>
<script setup>import{ref}from'vue';import{useRouter}from'vue-router';import api from'../services/api';import AppAlert from'../components/AppAlert.vue';import PasswordFields from'../components/PasswordFields.vue';const roles=['Administrador','Recepcionista','Asesor de servicio','Técnico','Cliente'],form=ref({full_name:'',username:'',role:null,password:''}),valid=ref(false),loading=ref(false),error=ref(''),router=useRouter();async function submit(){loading.value=true;error.value='';try{await api.post('/auth/register',{...form.value,roles:[form.value.role]});router.push('/ingresar')}catch(e){error.value=e.response?.data?.detail||'No fue posible registrar la cuenta'}finally{loading.value=false}}</script>
